<template>
  <div>

    <div class="loginRegister">
      <el-row style="height: 100%;" >
      <el-col :span="12" style="background-color: rgba(181,250,165,0.87);border-top-left-radius: 15px;border-bottom-left-radius: 15px">
        <img src="../../../assets/logo.png" >
      </el-col>
      <el-col :span="12" >
      <el-form :model="_userData" class="loginForm">

          <h3 style="padding-right:10px;" class="login-title">
            登录
          </h3>

        <el-form-item label="账号">
          <el-input v-model="_userData.userName" placeholder="请输入用户名/邮箱"/>
        </el-form-item>
        <el-form-item label="密码">
          <el-input v-model="_userData.password" placeholder="请输入密码"/>
        </el-form-item>
        <el-form-item>
          <el-button type="primary" style="width: 100%;background-color: #505458;border: none" @click="userLogin(_userData)">登录</el-button>
        </el-form-item>

      </el-form>
        <div id="registerOrFindPswd">
          <a href="#/register" style="text-decoration: none">注册账号</a>
          <el-divider direction="vertical" />
          <a href="" style="text-decoration: none">忘记密码</a>
        </div>
      </el-col>
      </el-row>
    </div>
  </div>

</template>

<script setup>
import {onMounted, reactive, ref} from "vue";
import {openShpFile} from "@/api/FileApi";
import {login} from "@/api/loginApi";
import {setToken} from "@/utils/auth";
import { useRouter } from 'vue-router';
import router, {routes} from "@/router/index"
import {ElMessage} from "element-plus";

let _userData=ref({
  userName:'',
  password:''
})

const userLogin = (user) => {
  localStorage.removeItem("userInfo")
  localStorage.removeItem("token")
  login(user).then(res=>{
    if(res.status){
      console.log(res.data)
      setToken(res.data.token)
      //console.log(localStorage.getItem('token'));
      // 存储用户信息
      localStorage.setItem("userInfo",JSON.stringify(res.data.userInfo))
      localStorage.setItem("token",res.data.token)
      //const router=useRouter();
      router.push({path:'/'})
      ElMessage({
        message: '登录成功',
        type: 'success',
      })
    }else{
      ElMessage.error(res.message)
    }
    // 登录成功记录token和用户信息，登录失败给对应提示

   //  if(localStorage.getItem('logUrl')){
   //    this.$router.push({path:'/MainPage'})
   //  }else{
   //    this.$router.push('/MainPage'})
   //  }
  })
}
</script>

<style scoped>
.loginForm{
  padding: 30px;
}
#registerOrFindPswd {
  display: flex;
  justify-content: center; /* 水平居中 */
  height: 100px; /* 或者你需要的高度 */
}
</style>