import axios from "@/http/axios";

export const openShpFile=(path)=>{
    return axios({
        url:'/file/openShpFile',
        method:'post',
        params:{'filePath':path}
    })
}
export const getShpFile=(shpFile)=>{
    console.log("tttttt",shpFile)
    return axios({
        url:'/file/getShpFile',
        method:'post',
        // headers:{'Content-Type':'application/x-www-form-urlencoded'},
        headers: {
            'Content-Type': 'application/json'
        },
        data:shpFile,
    })
}

export const getShpFileAndDownload=(shpFile)=>{

    return axios({
        url:'/file/getShpFileAndDownload',
        method:'post',
        // headers:{'Content-Type':'application/x-www-form-urlencoded'},
        headers: {
            'Content-Type': 'application/json'
        },
        data:shpFile,
    })
}

export const downloadFile=(fileStorePath)=>{
    return axios({
        url:'/file/download',
        method:'get',
        params:{
            'fileStorePath':fileStorePath
        }
    })
}

export const downloadShpFile=(fileStorePath)=>{
    return axios({
        url:'/file/downloadShpFile',
        method:'get',
        params:{
            'fileStorePath':fileStorePath
        }
    })
}


export default {openShpFile,getShpFile,downloadFile,downloadShpFile,getShpFileAndDownload}
