async function GetMapInfo() {
  // 第一步 获取文件列表
  const loginUserId=JSON.parse(localStorage.getItem("userInfo")).userId
 // const {data} = await getShpFile({'userId':loginUserId});
  const {data} = await getShpFileAndDownload({'userId':loginUserId});
  allFileList.value = data;
  console.log("allfile:",allFileList.value)
  // 第二部 循环获取每一项的细信息
  data.map(async (fileItem) => {
    // 解析文件地址
    const ParseTheFilePath = `${store.state.myDownloadPath}\\${loginUserId}\\${fileItem?.fileName}\\${fileItem?.fileName}.shp`
    // 获取文件信息
    const GetShpFile = await openShpFile(ParseTheFilePath);
    console.log(">>>3333<<<", GetShpFile)
    // 为没有个图形添加一个文件来源属性
    GetShpFile.data.featureCollection.features.forEach((e)=>{
      e.properties.__ParseTheFilePath = ParseTheFilePath;
    })

    // 生成矢量图层
    getVectorLayers(GetShpFile.data.fileName,GetShpFile.data.featureCollection)
  })

  createMap();
}

