const getMultiPolygonCoordinates =(e,shpInfo)=>{//处理MutiPolygon几何类型数据

  shpInfo.forEach((e) => {
    const _Key = e[0];
    const _Value = e[1];

    if (_Key === "geometry") {
      // 获取坐标点位信息
      const PointCoordinate = _Value?.flatCoordinates || [];
      const group= _Value?.endss_ || [];
      const multiPolyResult =[]
      if(group.length===1){
        let poly=[]
        let subGroup=group[0]
        if(subGroup.length===1){
          let subPoly=[]
          for(let i=0;i<group[0];i+=2){
            subPoly.push(PointCoordinate.slice(i, i + 2))
            _data.coordinateList.push(PointCoordinate.slice(i, i + 2))
          }
          poly.push(subPoly)
        }else{
          for(let k=0;k<subGroup.length;k++){
            let subPoly=[]
            let start=0
            if(k===0){
              start=0
            }else{
              start=subGroup[k-1]
            }
            let end=subGroup[k]
            for(let i=start;i<end;i+=2){
              subPoly.push(PointCoordinate.slice(i, i + 2))
              _data.coordinateList.push(PointCoordinate.slice(i, i + 2))
            }
            poly.push(subPoly)
          }
        }
        multiPolyResult.push(poly)
      }
      else{
        for(let j=0;j<group.length;j++){
          let poly=[]
          let subGroup=group[j]
          if(subGroup.length===1){
            let subPoly=[]
            let start2=0
            if(j===0){
              start2=0
            }else{
              start2=group[j-1][group[j-1].length-1]//获取起始下标
            }
            for(let i=start2;i<subGroup[0];i+=2){
              subPoly.push(PointCoordinate.slice(i, i + 2))
              _data.coordinateList.push(PointCoordinate.slice(i, i + 2))
            }
            poly.push(subPoly)
          }else{
            for(let k=0;k<subGroup.length;k++){
              let subPoly=[]
              let start1=0
              if(k===0){
                start1=0
              }else{
                start1=subGroup[k-1]
              }
              let end1=subGroup[k]
              for(let i=start1;i<end1;i+=2){
                subPoly.push(PointCoordinate.slice(i, i + 2))
                _data.coordinateList.push(PointCoordinate.slice(i, i + 2))
              }
              poly.push(subPoly)
            }
          }
          multiPolyResult.push(poly)

        }
      }
      console.log("poly:",multiPolyResult)
      // _data.coordinateList
      _data.ShpFeatureInfo.geometryJson.coordinates=multiPolyResult;
    } else {
      if(_Key !== "__ParseTheFilePath"){
        _data.ShpFeatureInfo.shpAttrMap[_Key]=_Value
      }else{
        _data.ShpFeatureInfo[_Key]=_Value
      }
    }
  })
}

