<template>
  <div style="margin-top: 15px">
    <el-dialog :visible.sync="visible">
    <el-input placeholder="请选择文件" v-model="textarea">
      <el-button
          slot="append"
          icon="el-icon-folder-opened"
          @click="openFile"
      ></el-button>
    </el-input>
    <input
        type="file"
        name="filename"
        id="open"
        style="display: none"
        @change="changeFile"
    />
    </el-dialog>
  </div>
</template>

<script setup>
// 导入组件
import {ref} from "vue";

const textarea=ref("");

const visible=ref(false)

const openFile = () => {
  document.getElementById("open").click();
}
const changeFile = () => {
  const fu = document.getElementById("open");
  if (fu == null) return;
  textarea.value = fu.files[0].name;
  console.log(fu.files[0].name);
}



</script>

