import { createStore } from 'vuex'

const store = createStore({
    state () {
        return {
            downloadFileIdList:[],
            //myDownloadPath:"D:\\shp-gis\\geotools-backend\\fileSpace\\"
            // myDownloadPath:"../../fileSpace"
            myDownloadPath:"/usr/local/fileSpace/"
            //myDownloadPath:"../../../../fileSpace"
        }
    },
    actions: {
        pushIdList(state,fileId){
            state.downloadFileIdList.push(fileId)
        },
        popIdList(state,fileId){
            state.downloadFileIdList.filter(item=>item==fileId)
        }
    },
    getters:{
        getDownloadFileIdList(state) {
            return state.downloadFileIdList;
        },
    }
})

export default store;
