<template>
  <div>
    <div class="loginRegister" id="registerContainer">
      <el-row style="height: 100%;" >
        <el-col :span="12" style="background-color: rgba(181,250,165,0.87);border-top-left-radius: 15px;border-bottom-left-radius: 15px">
          <img src="../../../assets/logo.png" >
        </el-col>
        <el-col :span="12" >
          <el-form :model="_registerUserData" class="registerForm" label-width="70px" label-position="left">
              <h3 style="padding-right:10px;" class="login-title">
                注册
              </h3>
            <el-form-item label="账号">
              <el-input v-model="_registerUserData.userName" placeholder="请输入用户名/邮箱"/>
            </el-form-item>
            <el-form-item label="密码">
              <el-input v-model="_registerUserData.password" placeholder="请输入密码"/>
            </el-form-item>
            <el-form-item label="确认密码">
              <el-input v-model="_registerUserData.checkPassword" placeholder="再次输入密码"/>
            </el-form-item>
            <el-form-item label="邮箱">
              <el-input v-model="_registerUserData.email" placeholder="请输入邮箱，用于登录和密码找回"/>
            </el-form-item>
            <el-form-item label="姓氏">
              <el-input v-model="_registerUserData.creatorLastname" placeholder="姓氏"/>
            </el-form-item>
            <el-form-item label="名">
              <el-input v-model="_registerUserData.creatorFirstname" placeholder="名"/>
            </el-form-item>

              <el-button type="primary" style="width: 100%;background-color: #505458;border: none" @click="submitRegisterForm(_registerUserData)">注册</el-button>

          </el-form>
          <div id="backToLogin">
            <a href="#/login" style="text-decoration: none">已有帐号，立即登录</a>
          </div>
        </el-col>
      </el-row>
    </div>
  </div>
</template>

<script setup>
import {onMounted, reactive, ref} from "vue";
import {login} from "@/api/loginApi";
import {setToken} from "@/utils/auth";
import router from "@/router";
import {register} from "@/api/userApi";
import {ElMessage} from "element-plus";

let _registerUserData=ref({
  checkPassword:'',
  userName:'',
  password:'',
  email:'',
  creatorFirstname:'',
  creatorLastname:''
})

const submitRegisterForm = (user) => {
  register(user).then(res=>{
    console.log(res)
    if(res.status){
      ElMessage({
        message: '注册成功',
        type: 'success',
      })
    }else{
      ElMessage.error(res.message)
    }
  })
}
</script>

<style scoped>
.registerForm{
  padding: 30px;
}
#backToLogin {
  display: flex;
  justify-content: center; /* 水平居中 */
  height: 100px; /* 或者你需要的高度 */
}
#registerContainer{
  width: 800px;
  height: 600px;
  margin: 100px auto;
}
</style>